function mapgen_ground_truth_anchor_status($body) js {
  const text = $body.text;
  if (/\(legacy router\)/i.test(text)) return "ok";
  return /^##\s+Ground truth anchors\s*$/im.test(text) ? "ok" : "missing";
}

